result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/capacity.py", "content": """"Capacity analysis over synthetic clinic visit volumes."""

import math

from gen import CLINICS, N_WEEKS, generate

SLOTS_PER_DAY = {"clinicA": 100, "clinicB": 150, "clinicC": 75}


def weekly_utilization(visits_by_clinic):
    """utilization[clinic][week] = total visits / (slots_per_day * 5)."""
    util = {}
    for clinic, rows in visits_by_clinic.items():
        slots_week = SLOTS_PER_DAY[clinic] * 5
        per_week = {w: 0 for w in range(1, N_WEEKS + 1)}
        for r in rows:
            per_week[r["week"]] += r["visits"]
        util[clinic] = {
            w: per_week[w] / slots_week for w in range(1, N_WEEKS + 1)
        }
    return util


def overflow_days(visits_by_clinic):
    """overflow[clinic] = number of days where visits > slots."""
    return {
        clinic: sum(1 for r in rows if r["visits"] > SLOTS_PER_DAY[clinic])
        for clinic, rows in visits_by_clinic.items()
    }


def suggested_slots(visits_by_clinic):
    """suggested[clinic] = ceil(p95(demand)/5)*5, p95 over all observed days."""
    suggested = {}
    for clinic, rows in visits_by_clinic.items():
        vals = sorted(r["visits"] for r in rows)
        # Linear-interpolation percentile (numpy default 'linear' method).
        k = 0.95 * (len(vals) - 1)
        lo, hi = math.floor(k), math.ceil(k)
        p95 = vals[lo] + (k - lo) * (vals[hi] - vals[lo])
        suggested[clinic] = int(math.ceil(p95 / 5) * 5)
    return suggested


def summary_markdown(visits_by_clinic):
    """Markdown table reconciling utilization, overflow, and suggestions."""
    util = weekly_utilization(visits_by_clinic)
    over = overflow_days(visits_by_clinic)
    sugg = suggested_slots(visits_by_clinic)
    lines = [
        "# Clinic Capacity Summary",
        "",
        "| Clinic | Mean Utilization | Max Utilization | Overflow Days | Suggested Slots |",
        "|---|---|---|---|---|",
    ]
    for clinic in CLINICS:
        us = list(util[clinic].values())
        lines.append(
            f"| {clinic} | {sum(us) / len(us):.3f} | {max(us):.3f} "
            f"| {over[clinic]} | {sugg[clinic]} |"
        )
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    data = generate()
    print(summary_markdown(data))
